import { mkdirSync } from "node:fs";

// Numbers chosen here:
const QUIET_START = "21:00"; // quiet hours begin (recipient-local)
const QUIET_END = "08:00"; // quiet hours end; 08:00 is allowed
const DISMISS_PAUSE_MS = 3 * 24 * 3600 * 1000; // after a swipe-away, same type pauses 3 days
const PER_TYPE_PER_DAY = 1; // pushes of one type per local day
const TOTAL_PER_DAY = 3; // pushes of all types per local day

function stateDir() {
  const dir = process.env.STATE_DIR;
  if (!dir) throw new Error("STATE_DIR is not set");
  mkdirSync(dir, { recursive: true });
  return dir;
}

function pickZone(user) {
  for (const z of [user?.deviceTimezone, user?.timezone]) {
    if (typeof z === "string" && z && z !== "UTC" && gkZoneOk(z)) return z;
  }
  return null;
}

const hold = (reason, extra = {}) => ({ send: false, reason, ...extra });

export async function decide({ user, candidate, now, flags } = {}) {
  const dir = stateDir();
  if (!user?.id || !candidate?.id || !candidate?.type || !(now instanceof Date) || isNaN(now)) {
    return hold("Missing user, candidate or time data, so nothing is sent.");
  }
  const ms = now.getTime();
  const uid = String(user.id);
  const type = String(candidate.type);

  // Same message id gets the same answer and spends nothing twice.
  const done = gkRead(dir, `sent:${candidate.id}`);
  if (done) return { send: true, reason: null };

  if (flags?.proactiveEnabled !== true) return hold("Proactive notifications are switched off by operations.");
  if (gkRead(dir, `optout:${uid}:${type}`)) return hold(`The user switched off ${type} notifications (opt-out).`);
  if (user.consents?.marketing !== true) return hold("The user has not given consent (marketing) for unsolicited notifications.");

  const zone = pickZone(user);
  if (!zone) return hold("The user's time zone is unknown or invalid, so the local time cannot be checked.");

  if (gkInWindow(ms, zone, QUIET_START, QUIET_END)) {
    const next = gkNextOpen(ms, zone, QUIET_END, QUIET_START);
    return hold(`Quiet hours (${QUIET_START} to ${QUIET_END} local time); try again at ${gkFmt(next, zone)}.`, { nextAllowedAt: new Date(next) });
  }

  const dis = gkRead(dir, `dismiss:${uid}:${type}`);
  if (dis && ms < dis.at + DISMISS_PAUSE_MS) {
    const next = dis.at + DISMISS_PAUSE_MS;
    return hold(`The user dismissed a ${type} notification recently (3-day pause); try again after ${gkFmt(next, zone)}.`, { nextAllowedAt: new Date(next) });
  }

  // Claim the message id before counting; give it back if we refuse.
  if (!gkClaim(dir, `claim:${candidate.id}`)) {
    for (let i = 0; i < 20; i++) {
      if (gkRead(dir, `sent:${candidate.id}`)) return { send: true, reason: null };
      await new Promise((r) => setTimeout(r, 25));
    }
    return hold("Another worker is already handling this notification.");
  }
  const day = gkDayKey(ms, zone);
  const nextDay = gkNextMidnight(ms, zone);
  const typeKey = `cap:${uid}:${type}:${day}`;
  const totalKey = `cap:${uid}:all:${day}`;
  const capHold = () => {
    gkUnclaim(dir, `claim:${candidate.id}`);
    return null;
  };
  if (!gkCount(dir, typeKey, PER_TYPE_PER_DAY).ok) {
    capHold();
    return hold(`Daily limit reached: ${PER_TYPE_PER_DAY} ${type} notification per day; try again at ${gkFmt(nextDay, zone)}.`, { nextAllowedAt: new Date(nextDay) });
  }
  if (!gkCount(dir, totalKey, TOTAL_PER_DAY).ok) {
    gkRefund(dir, typeKey);
    capHold();
    return hold(`Daily limit reached: ${TOTAL_PER_DAY} notifications per day; try again at ${gkFmt(nextDay, zone)}.`, { nextAllowedAt: new Date(nextDay) });
  }
  gkWrite(dir, `sent:${candidate.id}`, { at: ms, userId: uid, type });
  return { send: true, reason: null };
}

export async function recordDismissal(userId, type, now) {
  const dir = stateDir();
  const at = now instanceof Date ? now.getTime() : typeof now === "number" ? now : Date.now();
  gkWrite(dir, `dismiss:${userId}:${type}`, { at });
}

export async function optOut(userId, type) {
  gkWrite(stateDir(), `optout:${userId}:${type}`, { at: Date.now() });
}
